import { Component, useId, useState } from "react";
import styles from "./Accordion.module.css";
import { Icon } from "./Icon.jsx";
import { cx } from "./util.js";

// The legacy kit's collapse container: a class component that hides its
// content without unmounting it.
export class Collapse extends Component {
    shouldComponentUpdate(next) {
        return next.open !== this.props.open || next.children !== this.props.children;
    }

    render() {
        const { open, id, children } = this.props;
        return <div id={id} className={cx(styles.collapse, open && styles.open)} hidden={!open}>{children}</div>;
    }
}

export function Accordion({ title, defaultOpen = true, children, className, testId }) {
    const [open, setOpen] = useState(defaultOpen);
    const id = useId();
    return (
        <section className={cx(styles.accordion, className)} data-testid={testId}>
            <button type="button" className={styles.trigger} aria-expanded={open} aria-controls={id} onClick={() => setOpen(!open)}>
                <span className={styles.title}>{title}</span>
                <Icon name={open ? "chevron-up" : "chevron-down"} size="small" />
            </button>
            <Collapse open={open} id={id}>{children}</Collapse>
        </section>
    );
}
