import { forwardRef } from "react";
import styles from "./Card.module.css";
import { cx, useKitRoot } from "./util.js";

export const Card = forwardRef(function Card({ as: Element = "div", variant = "elevated", padding = true, mixin, className, children, ...rest }, ref) {
    const root = useKitRoot([styles.card, styles[variant], padding && styles.padded], mixin, className, undefined, ref);
    return <Element {...root} {...rest}>{children}</Element>;
});

export function CardSection({ divider, className, children }) {
    return <div className={cx(styles.section, divider && styles.divider, className)}>{children}</div>;
}
