// The property page's React islands, by the name of their slot in the
// server HTML. The server render and the client hydration share this list.
import { IslandProviders } from "./IslandProviders.jsx";
import { HighlightsIsland } from "./islands/HighlightsIsland.jsx";
import { ReviewsIsland } from "./islands/ReviewsIsland.jsx";

export const ISLANDS = {
    highlights: HighlightsIsland,
    reviews: ReviewsIsland,
};

export function Island({ name, client, config, variables }) {
    const Component = ISLANDS[name];
    return (
        <IslandProviders client={client} config={config} surface={`property-${name}`}>
            <Component variables={variables} />
        </IslandProviders>
    );
}
