// The results page's single React root: the providers every
// micro-frontend reads, around the page shell.
import { useCallback } from "react";
import { ApolloProvider } from "@apollo/client";
import {
    AnnouncerProvider, CurrencyProvider, ErrorBoundary, ExperimentProvider, FeatureFlagsProvider, I18nProvider, LayerProvider, PageProvider, SearchStateProvider, TrackingScope,
    UserProvider, ViewportProvider,
} from "travel-platform";
import "./catalog.js";
import { ThemeProvider } from "./ThemeProvider.jsx";
import { PropertyNavigationContext } from "./navigation.js";
import { SearchResultsPage } from "./results/SearchResultsPage.jsx";

const LOGGED_OUT = { loggedIn: false, memberLevel: 0 };
const PAGE = { pageName: "searchresults", product: "stays" };
const DESKTOP = { kind: "desktop", width: 1440 };

export function App({ client, config, openProperty }) {
    const getLayerContainer = useCallback(() => document.getElementById("travel-layers"), []);
    return (
        <ApolloProvider client={client}>
            <I18nProvider locale={config.locale}>
                <CurrencyProvider currency={config.currency}>
                    <FeatureFlagsProvider flags={config.flags}>
                        <UserProvider user={LOGGED_OUT}>
                            <ViewportProvider viewport={DESKTOP}>
                                <PageProvider page={PAGE}>
                                    <ExperimentProvider assignments={config.experiments}>
                                        <TrackingScope surface="searchresults">
                                            <LayerProvider getContainer={getLayerContainer}>
                                                <AnnouncerProvider>
                                                    <SearchStateProvider initialState={config.initialSearch}>
                                                        <ThemeProvider theme="light">
                                                            <PropertyNavigationContext.Provider value={openProperty}>
                                                                <ErrorBoundary name="page">
                                                                    <SearchResultsPage config={config} />
                                                                </ErrorBoundary>
                                                            </PropertyNavigationContext.Provider>
                                                        </ThemeProvider>
                                                    </SearchStateProvider>
                                                </AnnouncerProvider>
                                            </LayerProvider>
                                        </TrackingScope>
                                    </ExperimentProvider>
                                </PageProvider>
                            </ViewportProvider>
                        </UserProvider>
                    </FeatureFlagsProvider>
                </CurrencyProvider>
            </I18nProvider>
        </ApolloProvider>
    );
}
