import { memo } from "react";
import { Icon, Inline, Stack, Text } from "@kit/index.js";
import { LocalizedText, Translate, useExperiment, useLocalized, useTranslation } from "travel-platform";
import { useCard } from "./CardContext.js";
import { useCardFragment } from "./fragments.js";
import styles from "./PropertyCard.module.css";

function BedSummary({ beds }) {
    const localized = useLocalized();
    return <Text variant="small_1" className={styles.beds}>{beds.map((bed) => localized(bed.text)).join(", ")}</Text>;
}

function PolicyLine({ policy, kind }) {
    return (
        <Inline gap={1} wrap className={styles[kind]} data-testid={kind}>
            <span className={styles.tick} aria-hidden="true" />
            <Text as="span" variant="small_2" className={styles.policyTitle}><LocalizedText value={policy.title} /></Text>
            {policy.detail ? <Text as="span" variant="small_1" className={styles.policyDetail}><LocalizedText value={policy.detail} /></Text> : null}
        </Inline>
    );
}

function MealPlan({ mealPlan }) {
    return (
        <Inline gap={1} className={styles.meal}>
            <Icon name={mealPlan.icon.name} size="small" />
            <Text as="span" variant="small_1"><LocalizedText value={mealPlan.text} /></Text>
        </Inline>
    );
}

function UnitName({ name }) {
    const localized = useLocalized();
    return <Text variant="strong_2" className={styles.unitName}>{localized(name)}</Text>;
}

function OccupancyHint({ occupancy }) {
    const t = useTranslation();
    return <Text as="span" variant="small_1" color="alt" className={styles.occupancy} title={occupancy.text.text}>{t("sr.max_people", { count: occupancy.adults })}</Text>;
}

function Scarcity({ scarcity }) {
    const localized = useLocalized();
    const text = localized(scarcity.text);
    return <Text variant="small_2" className={styles.scarcity} aria-live="polite">{text}</Text>;
}

const Unit = memo(function Unit({ unit: fromList }) {
    const unit = useCardFragment("UnitConfigurationFields", fromList);
    return (
        <Stack gap={1} className={styles.unit} data-testid="recommended-units">
            <UnitName name={unit.name} />
            <BedSummary beds={unit.beds} />
            <OccupancyHint occupancy={unit.occupancy} />
            {unit.mealPlan ? <MealPlan mealPlan={unit.mealPlan} /> : null}
            {unit.cancellation ? <PolicyLine policy={unit.cancellation} kind="cancellation" /> : null}
            {unit.prepayment ? <PolicyLine policy={unit.prepayment} kind="prepayment" /> : null}
            {unit.scarcity ? <Scarcity scarcity={unit.scarcity} /> : null}
        </Stack>
    );
});

function DetailsToggle() {
    const { detailsOpen, setDetailsOpen, trackCard } = useCard();
    return (
        <button
            type="button"
            className={styles.detailsToggle}
            aria-expanded={detailsOpen}
            onClick={() => {
                trackCard(detailsOpen ? "card.unit_details_close" : "card.unit_details_open");
                setDetailsOpen(!detailsOpen);
            }}
            data-testid="unit-details-toggle"
        >
            <Translate id={detailsOpen ? "sr.hide_room_details" : "sr.room_details"} />
            <Icon name={detailsOpen ? "chevron-up" : "chevron-down"} size="small" />
        </button>
    );
}

export function CardUnits() {
    const { card } = useCard();
    const toggleVariant = useExperiment("sr_unit_config_toggle");
    return (
        <Stack gap={2} className={styles.units}>
            {card.recommendation ? <Text variant="strong_2" color="brand"><LocalizedText value={card.recommendation.title} /></Text> : null}
            {card.matchingUnits.map((unit) => <Unit key={unit.id} unit={unit} />)}
            {toggleVariant !== 2 ? <DetailsToggle /> : null}
        </Stack>
    );
}
