import { Fragment, useEffect, useRef } from "react";
import { RemoteComponent, useSearchState } from "travel-platform";
import { PropertyCard } from "../card/PropertyCard.jsx";
import { CardSkeleton } from "../card/CardSkeleton.jsx";
import { useResults } from "./ResultsContext.js";
import styles from "./Results.module.css";

// Scrolls the top of the list into view after a page change, within the
// page's own document.
function useScrollOnPageChange(listRef, page, loading) {
    const lastPage = useRef(page);
    useEffect(() => {
        if (loading || page === lastPage.current)
            return;
        lastPage.current = page;
        const list = listRef.current;
        if (!list)
            return;
        const top = list.getBoundingClientRect().top + window.scrollY - 16;
        if (top < window.scrollY)
            document.scrollingElement.scrollTop = top;
    }, [listRef, page, loading]);
}

function LoadingOverlay() {
    return (
        <div className={styles.loadingOverlay} aria-hidden="true" data-testid="results-loading">
            <CardSkeleton />
            <CardSkeleton />
            <CardSkeleton />
        </div>
    );
}

export function ResultsList() {
    const { result, loading } = useResults();
    const { state } = useSearchState();
    const listRef = useRef(null);
    useScrollOnPageChange(listRef, state.page, loading);
    if (!result)
        return <LoadingOverlay />;
    const banners = new Map(result.banners.map((banner) => [banner.position, banner]));
    return (
        <div ref={listRef} className={styles.list} aria-busy={loading} data-testid="results-list">
            {loading ? <LoadingOverlay /> : null}
            {result.results.map((card, i) => (
                <Fragment key={card.id}>
                    {banners.has(i) ? <RemoteComponent module="merchBanners/MerchBanner" props={{ banner: banners.get(i) }} /> : null}
                    <PropertyCard card={card} index={i} />
                </Fragment>
            ))}
        </div>
    );
}
