// Boots the results page. Preparing loads the remote modules, every lazy
// chunk, the prepared GraphQL responses and the property page, so that no
// benchmark step waits for the network. Hydration then happens right away,
// or, in benchmark mode, when the first step asks for it.
import { hydrateRoot } from "react-dom/client";
import {
    benchmarkMode, createApolloClient, createCache, flushDebounced, getPageConfig, loadRemoteModules, nextEvent, preloadLazy, preloadResponses, servedRequests, tracker, trackReactRoot, whenIdle,
} from "travel-platform";
import { App } from "./App.jsx";
import { REMOTE_LOADERS } from "./remotes.js";
import { openPropertyPage, preloadPropertyPages } from "./property/PropertyPage.jsx";

const config = getPageConfig();
const recoverableErrors = [];
let root = null;

async function prepare() {
    await loadRemoteModules(REMOTE_LOADERS);
    await preloadLazy();
    await Promise.all([preloadResponses(document.baseURI), preloadPropertyPages(document.baseURI, config.propertyPages)]);
}

function openProperty(event, propertyId) {
    if (openPropertyPage(propertyId, config))
        event.preventDefault();
}

function hydrate() {
    const snapshot = JSON.parse(document.getElementById("apollo-state").textContent);
    const cache = createCache();
    cache.restore(snapshot);
    const client = createApolloClient({ cache });
    root = hydrateRoot(document.getElementById("travel-root"), <App client={client} config={config} openProperty={openProperty} />, {
        identifierPrefix: "sr-",
        onRecoverableError: (error) => recoverableErrors.push(String(error?.message ?? error)),
    });
    trackReactRoot(root);
}

const ready = prepare();

window.travelWorkload = {
    ready,
    hydrate,
    whenIdle,
    nextEvent,
    flushDebounced,
    stats: () => ({ recoverableErrors, requests: servedRequests(), telemetry: tracker.sent }),
};

if (!benchmarkMode)
    ready.then(hydrate);
