import { useCallback } from "react";
import { ApolloProvider } from "@apollo/client";
import { CurrencyProvider, ErrorBoundary, ExperimentProvider, I18nProvider, LayerProvider, PageProvider, TrackingScope, UserProvider } from "travel-platform";
import "./catalog.js";

const LOGGED_OUT = { loggedIn: false, memberLevel: 0 };
const PAGE = { pageName: "hotel", product: "stays" };

// The providers around each island of the property page. Islands are
// separate React roots that share one Apollo client.
export function IslandProviders({ client, config, surface, children }) {
    const getLayerContainer = useCallback(() => document.getElementById("travel-layers"), []);
    return (
        <ApolloProvider client={client}>
            <I18nProvider locale={config.locale}>
                <CurrencyProvider currency={config.currency}>
                    <UserProvider user={LOGGED_OUT}>
                        <PageProvider page={PAGE}>
                            <ExperimentProvider assignments={config.experiments}>
                                <TrackingScope surface={surface}>
                                    <LayerProvider getContainer={getLayerContainer}>
                                        <ErrorBoundary name={surface}>{children}</ErrorBoundary>
                                    </LayerProvider>
                                </TrackingScope>
                            </ExperimentProvider>
                        </PageProvider>
                    </UserProvider>
                </CurrencyProvider>
            </I18nProvider>
        </ApolloProvider>
    );
}
