import { memo } from "react";
import { Badge, Icon, Inline, Rating, Stack, Text, Tooltip } from "@kit/index.js";
import { Translate, useLocalized } from "travel-platform";
import { useCard } from "./CardContext.js";
import { useCardFragment } from "./fragments.js";
import { useOpenProperty } from "../navigation.js";
import { TrackedLink } from "./tracked.js";
import styles from "./PropertyCard.module.css";

function StarRating({ rating }) {
    const localized = useLocalized();
    return (
        <Tooltip text={localized(rating.caption)}>
            <span className={styles.stars} data-testid="rating-stars" tabIndex={0}>
                <Rating value={rating.value} symbol={rating.symbol} label={localized(rating.a11yLabel)} />
            </span>
        </Tooltip>
    );
}

const PreferredMark = memo(function PreferredMark({ plus }) {
    return <span className={styles.preferred} aria-label="Preferred partner"><Icon name="thumbs-up" size="small" color={plus ? "brand" : "callout"} /></span>;
});

function TypeLabel({ type }) {
    const localized = useLocalized();
    return <Text as="span" variant="small_2" className={styles.typeLabel}>{localized(type.name)}</Text>;
}

function CardTitle() {
    const { card, trackCard } = useCard();
    const openProperty = useOpenProperty();
    const { details } = card.links;
    return (
        <Text as="h3" variant="headline_3" className={styles.title}>
            <TrackedLink href={details.href} target={details.target} rel={details.rel} className={styles.titleLink} trackingName="card.title" trackingData={{ position: card.position }} onClick={(e) => { trackCard("card.title_click"); openProperty(e, card.id); }} data-testid="title-link">
                <span data-testid="title">{card.basics.name}</span>
            </TrackedLink>
        </Text>
    );
}

function CardSubtitle() {
    const { card } = useCard();
    const { basics } = card;
    return (
        <Inline gap={2} wrap className={styles.subtitle}>
            <TypeLabel type={basics.accommodationType} />
            {basics.flags.isNew ? <Badge variant="brand" emphasis="subtle"><Translate id="sr.new_to_site" /></Badge> : null}
            {basics.chain ? <Text as="span" variant="small_1" className={styles.chain}>{basics.chain.name}</Text> : null}
        </Inline>
    );
}

export function CardHeader() {
    const { card } = useCard();
    const basics = useCardFragment("PropertyCardBasics", card.basics);
    return (
        <Stack gap={1} className={styles.header}>
            <Inline gap={2} wrap className={styles.titleRow}>
                <CardTitle />
                {basics.starRating ? <StarRating rating={basics.starRating} /> : null}
                {basics.flags.isPreferred ? <PreferredMark plus={basics.flags.isPreferredPlus} /> : null}
            </Inline>
            <CardSubtitle />
        </Stack>
    );
}
