import { forwardRef, useCallback, useRef } from "react";
import styles from "./Menu.module.css";
import { Icon } from "./Icon.jsx";
import { cx } from "./util.js";

// A list of options in a popover, with roving focus.
export function ListMenu({ items, selected, onSelect, label, testId }) {
    const listRef = useRef(null);
    const onKeyDown = useCallback((event) => {
        const options = [...listRef.current.querySelectorAll("[role=menuitemradio]")];
        const index = options.indexOf(document.activeElement);
        if (event.key === "ArrowDown" || event.key === "ArrowUp") {
            event.preventDefault();
            options[(index + (event.key === "ArrowDown" ? 1 : options.length - 1)) % options.length]?.focus();
        }
    }, []);
    return (
        <ul ref={listRef} role="menu" aria-label={label} className={styles.menu} onKeyDown={onKeyDown} data-testid={testId}>
            {items.map((item) => <MenuItem key={item.id} item={item} checked={item.id === selected} onSelect={onSelect} />)}
        </ul>
    );
}

const MenuItem = forwardRef(function MenuItem({ item, checked, onSelect }, ref) {
    return (
        <li role="none" className={styles.row}>
            <button ref={ref} type="button" role="menuitemradio" aria-checked={checked} aria-label={item.a11yLabel} className={cx(styles.item, checked && styles.checked)} onClick={() => onSelect(item.id)} data-id={item.id}>
                <span className={styles.label}>{item.label}</span>
                {checked ? <Icon name="check" size="small" className={styles.check} /> : null}
            </button>
        </li>
    );
});
