import { useState } from "react";
import { Icon } from "@kit/index.js";
import { useTrack, useTranslation } from "travel-platform";
import styles from "./Results.module.css";

export function ViewToggle() {
    const t = useTranslation();
    const track = useTrack();
    const [view, setView] = useState("list");
    const select = (next) => {
        setView(next);
        track("results.view_toggle", { view: next });
    };
    return (
        <div role="radiogroup" aria-label={t("sr.view")} className={styles.viewToggle}>
            {[["list", "sr.list_view", "district"], ["grid", "sr.grid_view", "square"]].map(([id, key, icon]) => (
                <button key={id} type="button" role="radio" aria-checked={view === id} className={styles.viewButton} onClick={() => select(id)}>
                    <Icon name={icon} size="small" />
                    <span>{t(key)}</span>
                </button>
            ))}
        </div>
    );
}
