// Opening a property from the results. On the reference site the property
// page is a separate document in a new tab, with legacy jQuery code around
// two React islands. The workload swaps that page into the same document:
// it hides the results root (without unmounting it, as another tab would
// leave it alone), inserts the server HTML, runs the legacy ready handlers
// and hydrates the islands.
import { hydrateRoot } from "react-dom/client";
import { createApolloClient, createCache, emitStepEvent, startSpan, track, trackReactRoot } from "travel-platform";
import { Island } from "./Islands.jsx";

const pages = new Map();

export async function preloadPropertyPages(baseUrl, ids) {
    await Promise.all(ids.map(async (id) => {
        const response = await fetch(new URL(`property/${id}.html`, baseUrl));
        pages.set(id, await response.text());
    }));
}

export function hasPropertyPage(id) {
    return pages.has(id);
}

function islandsReady(count) {
    let seen = 0;
    return new Promise((resolve) => {
        const onReady = () => {
            if (++seen === count) {
                window.removeEventListener("travel-property-island-ready", onReady);
                resolve();
            }
        };
        window.addEventListener("travel-property-island-ready", onReady);
    });
}

export function openPropertyPage(id, config) {
    const html = pages.get(id);
    if (!html)
        return false;
    const span = startSpan("property.open", { propertyId: id });
    document.getElementById("travel-root").hidden = true;
    const container = document.getElementById("property-page");
    container.innerHTML = html;
    container.hidden = false;
    document.scrollingElement.scrollTop = 0;

    window.TravelLegacy.boot(container);

    const snapshot = JSON.parse(container.querySelector("#property-apollo-state").textContent);
    const islandConfig = JSON.parse(container.querySelector("#property-config").textContent);
    const cache = createCache();
    cache.restore(snapshot);
    const client = createApolloClient({ cache });
    const slots = container.querySelectorAll("[data-island]");
    const ready = track(islandsReady(slots.length).then(() => {
        span.end();
        emitStepEvent("property-ready", { propertyId: id });
    }));
    for (const slot of slots) {
        const name = slot.dataset.island;
        const root = hydrateRoot(slot, <Island name={name} client={client} config={config} variables={islandConfig.variables} />, { identifierPrefix: `pp-${name}-` });
        trackReactRoot(root);
    }
    return ready;
}
