// The search state of the results page and its GraphQL variables. The client
// and the build share this module, so that the variables the app sends match
// the keys of the prepared responses exactly.

export const ROWS_PER_PAGE = 20;
export const LOCALE = "en-gb";
export const CURRENCY = "EUR";

export function stableStringify(value) {
    if (Array.isArray(value))
        return `[${value.map(stableStringify).join(",")}]`;
    if (value && typeof value === "object")
        return `{${Object.keys(value).sort().filter((key) => value[key] !== undefined).map((key) => `${JSON.stringify(key)}:${stableStringify(value[key])}`).join(",")}}`;
    return JSON.stringify(value);
}

export function responseKey(operationName, variables) {
    return `${operationName}:${stableStringify(variables ?? {})}`;
}

export function normalizeFilters(filters) {
    return [...new Set(filters)].sort();
}

export function searchVariables(state) {
    return {
        input: {
            destination: { destId: state.destId, destType: state.destType },
            dates: { checkin: state.checkin, checkout: state.checkout },
            occupancy: { adults: state.adults, children: state.children, rooms: state.rooms, childrenAges: [] },
            filters: { selected: normalizeFilters(state.filters) },
            sorting: { order: state.sort },
            pagination: { offset: state.page * ROWS_PER_PAGE, rowsPerPage: ROWS_PER_PAGE },
            metaContext: { locale: LOCALE, currency: CURRENCY, device: "DESKTOP" },
        },
    };
}

export function autocompleteVariables(query) {
    return { input: { query, locale: LOCALE, limit: 8, purpose: "SEARCHBOX" } };
}

export function propertyVariables(propertyId, state) {
    return { id: propertyId, dates: { checkin: state.checkin, checkout: state.checkout }, occupancy: { adults: state.adults, children: state.children, rooms: state.rooms } };
}

export function reviewsVariables(propertyId) {
    return { id: propertyId, page: 0, pageSize: 10, sort: "MOST_RELEVANT" };
}

// The query string of a results URL, in the reference site's shape.
export function searchParams(state) {
    const params = new URLSearchParams();
    params.set("dest_id", state.destId);
    params.set("dest_type", state.destType);
    params.set("checkin", state.checkin);
    params.set("checkout", state.checkout);
    params.set("group_adults", String(state.adults));
    params.set("group_children", String(state.children));
    params.set("no_rooms", String(state.rooms));
    if (state.filters.length)
        params.set("nflt", normalizeFilters(state.filters).join(";"));
    if (state.sort !== "popularity")
        params.set("order", state.sort);
    if (state.page)
        params.set("offset", String(state.page * ROWS_PER_PAGE));
    return params;
}

export function nightsBetween(checkin, checkout) {
    return Math.round((Date.parse(`${checkout}T00:00:00Z`) - Date.parse(`${checkin}T00:00:00Z`)) / 86400000);
}

// The price range filter, as the slider writes it: price=EUR-<min>-<max>-1.
export function priceFilter(min, max) {
    return `price=${CURRENCY}-${min}-${max}-1`;
}

export function parsePriceFilter(filter) {
    const match = /^price=([A-Z]+)-(\d+)-(\d+)-1$/.exec(filter);
    return match ? { min: Number(match[2]), max: Number(match[3]) } : null;
}
