import { Icon, Price, Text } from "@kit/index.js";
import { LocalizedText, Translate, useTranslation } from "travel-platform";
import { useCard } from "./CardContext.js";
import styles from "./PropertyCard.module.css";

function BedRow({ bed }) {
    return (
        <li className={styles.bedRow}>
            <Icon name={bed.type.icon.name} size="medium" />
            <span><LocalizedText value={bed.text} /></span>
        </li>
    );
}

function UnitConfiguration({ unit }) {
    const t = useTranslation();
    return (
        <section className={styles.unitConfig} data-testid="unit-configuration">
            <Text as="h4" variant="strong_2"><LocalizedText value={unit.name} /></Text>
            <dl className={styles.facts}>
                <dt><Translate id="sr.beds" /></dt>
                <dd><ul className={styles.bedList}>{unit.beds.map((bed, i) => <BedRow key={i} bed={bed} />)}</ul></dd>
                <dt><Translate id="sr.room_size" /></dt>
                <dd><LocalizedText value={unit.size.text} /></dd>
                <dt><Icon name="person" size="small" /></dt>
                <dd>{t("sr.max_people", { count: unit.occupancy.adults })}</dd>
            </dl>
            <Price amount={unit.price.amountRounded} size="medium" />
        </section>
    );
}

export function UnitDetails() {
    const { card } = useCard();
    return (
        <div className={styles.unitDetails} data-testid="unit-details">
            {card.matchingUnits.map((unit) => <UnitConfiguration key={unit.id} unit={unit} />)}
        </div>
    );
}
