import { useEffect } from "react";
import { useQuery } from "@apollo/client";
import { Button, Card, Icon, IconButton, Inline, Stack, Text } from "@kit/index.js";
import { LocalizedText, RemoteComponent, Translate, emitStepEvent, useTrack, useTranslation } from "travel-platform";
import { PROPERTY_PAGE_QUERY } from "../queries.js";
import styles from "./Islands.module.css";

function Highlight({ item }) {
    return (
        <li className={styles.highlight}>
            <Icon name={item.icon.name} size="large" color="brand" />
            <div>
                <Text variant="strong_2"><LocalizedText value={item.title} /></Text>
                <Text variant="small_1"><LocalizedText value={item.body} /></Text>
            </div>
        </li>
    );
}

function PopularFacilities({ facilities }) {
    const t = useTranslation();
    return (
        <section className={styles.facilities}>
            <Text as="h2" variant="headline_3"><Translate id="pp.facilities_title" /></Text>
            <ul className={styles.facilityList}>
                {facilities.popular.map((facility) => (
                    <li key={facility.id} className={styles.facility}>
                        <Icon name={facility.icon.name} size="medium" color="constructive" />
                        <span><LocalizedText value={facility.text} /></span>
                    </li>
                ))}
            </ul>
        </section>
    );
}

export function HighlightsIsland({ variables }) {
    const t = useTranslation();
    const track = useTrack();
    const { data } = useQuery(PROPERTY_PAGE_QUERY, { variables, fetchPolicy: "cache-only" });
    const property = data?.property;
    useEffect(() => {
        if (property)
            emitStepEvent("property-island-ready", { island: "highlights" });
    }, [property]);
    if (!property)
        return null;
    const { highlights } = property;
    return (
        <Stack gap={4} data-testid="highlights-island">
            <Inline gap={1} justifyContent="end">
                <RemoteComponent module="wishlist/WishlistButton" props={{ propertyId: property.id, name: property.name, saved: property.wishlist.isSaved, a11yLabel: property.wishlist.a11yLabel.text, overlay: false }} />
                <IconButton icon="share" label={t("pp.share")} onClick={() => track("property.share")} />
                <Button variant="primary" onClick={() => track("property.reserve_top")} href="#rooms"><Translate id="pp.reserve" /></Button>
            </Inline>
            <Text variant="small_1" color="brand"><LocalizedText value={property.priceMatch.text} /></Text>
            <Card variant="neutral" className={styles.highlights}>
                <Text as="h2" variant="strong_1"><LocalizedText value={highlights.title} /></Text>
                <ul className={styles.highlightList}>{highlights.items.map((item) => <Highlight key={item.id} item={item} />)}</ul>
                {highlights.breakfast ? <Text variant="small_1"><LocalizedText value={highlights.breakfast.text} /></Text> : null}
                {highlights.parking ? <Text variant="small_1"><LocalizedText value={highlights.parking.text} /></Text> : null}
                <Text variant="small_1" color="constructive"><LocalizedText value={property.location.scoreText} /></Text>
                <Button variant="primary" wide href="#rooms"><LocalizedText value={highlights.cta.label} /></Button>
            </Card>
            <PopularFacilities facilities={property.facilities} />
        </Stack>
    );
}
