import { Icon, Inline, Stack, Text } from "@kit/index.js";
import { LocalizedText, Translate, useExperiment, useLocalized } from "travel-platform";
import { useCard } from "./CardContext.js";
import { useCardFragment } from "./fragments.js";
import { TrackedLink } from "./tracked.js";
import styles from "./PropertyCard.module.css";

function TransitHint({ transit }) {
    return (
        <Inline gap={1} className={styles.transit}>
            <Icon name={transit.icon.name} size="small" color="alt" />
            <Text as="span" variant="small_1"><LocalizedText value={transit.text} /></Text>
        </Inline>
    );
}

function DistrictLink({ district, href }) {
    return (
        <TrackedLink href={href} variant="small_1" className={styles.district} trackingName="card.district" trackingData={{ district: district.id }}>
            <LocalizedText value={district.name} />
        </TrackedLink>
    );
}

function Distance({ distance }) {
    const localized = useLocalized();
    return <Text as="span" variant="small_1" className={styles.distance} data-testid="distance">{localized(distance.text)}</Text>;
}

export function CardLocation() {
    const { card } = useCard();
    const { location } = useCardFragment("PropertyCardBasics", card.basics);
    const showTransit = useExperiment("sr_transit_hint") !== 2;
    return (
        <Stack gap={1} className={styles.location} data-testid="location">
            <Inline gap={2} wrap className={styles.locationRow}>
                <DistrictLink district={location.district} href={card.links.map.href} />
                {location.showMapLink ? <TrackedLink href={card.links.map.href} variant="small_1" trackingName="card.map"><Translate id="sr.show_on_map" /></TrackedLink> : null}
                <Distance distance={location.distance} />
            </Inline>
            {location.transit && showTransit ? <TransitHint transit={location.transit} /> : null}
        </Stack>
    );
}
