// Class name composition and the mixin contract: a `mixin` prop such as
// { marginBlockEnd: 4 } becomes custom properties on the element, which the
// shared .mixin class reads.
import { useCallback, useMemo, useRef } from "react";
import spacing from "@generated/spacing.module.css";

export function cx(...names) {
    let result = "";
    for (const name of names) {
        if (name)
            result = result ? `${result} ${name}` : name;
    }
    return result;
}

const SPACING_STEPS = { 0: "0", 0.5: "half", 1: "1x", 2: "2x", 3: "3x", 4: "4x", 5: "5x", 6: "6x", 8: "8x", 10: "10x", 12: "12x", 16: "16x" };
const MIXIN_PROPERTIES = {
    marginBlockStart: "margin-block-start",
    marginBlockEnd: "margin-block-end",
    marginInlineStart: "margin-inline-start",
    marginInlineEnd: "margin-inline-end",
    insetInlineStart: "inset-inline-start",
    insetBlockStart: "inset-block-start",
    flexGrow: "flex-grow",
    flexShrink: "flex-shrink",
    width: "width",
    maxWidth: "max-width",
};

export function spacingToken(step) {
    return `var(--tk-spacing-${SPACING_STEPS[step] ?? step})`;
}

export function mixinStyle(mixin, style) {
    if (!mixin)
        return style;
    const result = { ...style };
    for (const [key, value] of Object.entries(mixin)) {
        const property = MIXIN_PROPERTIES[key];
        if (property)
            result[`--tk_mixin_${property}`] = typeof value === "number" && key.startsWith("margin") ? spacingToken(value) : value;
    }
    return result;
}

export function mixinClass(mixin) {
    return mixin ? spacing.mixin : undefined;
}

export function spacingClass(prefix, step, breakpoint) {
    if (step === undefined || step === null)
        return undefined;
    const name = `${prefix}_${SPACING_STEPS[step] ?? step}${breakpoint ? `--${breakpoint}` : ""}`;
    return spacing[name];
}

// Responsive props are either a value or { base, medium, large }.
export function responsiveClasses(prefix, value) {
    if (value === undefined || value === null)
        return undefined;
    if (typeof value !== "object")
        return spacingClass(prefix, value);
    return cx(spacingClass(prefix, value.base), spacingClass(prefix, value.medium, "medium"), spacingClass(prefix, value.large, "large"));
}

// The root element props of a kit component: its class names, the mixin
// custom properties, and a ref that feeds both the kit's own element ref and
// the one the caller forwarded.
export function useKitRoot(classNames, mixin, className, style, forwardedRef) {
    const key = classNames.join(" ");
    const resolvedClassName = useMemo(() => cx(key, mixinClass(mixin), className), [key, mixin, className]);
    const resolvedStyle = useMemo(() => mixinStyle(mixin, style), [mixin, style]);
    const element = useRef(null);
    const ref = useCallback((node) => {
        element.current = node;
        if (typeof forwardedRef === "function")
            forwardedRef(node);
        else if (forwardedRef)
            forwardedRef.current = node;
    }, [forwardedRef]);
    return { className: resolvedClassName, style: resolvedStyle, ref };
}
